const err = $input.first().json;

const workflow_name = err.workflow?.name || "unknown workflow";
const node_name = err.execution?.lastNodeExecuted || "unknown node";
const error_message = err.execution?.error?.message || "No error message";
const execution_id = err.execution?.id || "";
const execution_url = "https://n8n.sauc.cat/execution/" + execution_id;

let shipping_code = "";
try {
  const lastData = err.execution?.data?.resultData?.runData;
  if (lastData) {
    const keys = Object.keys(lastData);
    for (const key of keys.slice(-5)) {
      const items = lastData[key]?.[0]?.data?.main?.[0] || [];
      for (const item of items) {
        if (item?.json?.shipping_code) {
          shipping_code = item.json.shipping_code;
          break;
        }
      }
      if (shipping_code) break;
    }
  }
} catch(e) {}

const subject = "[CTT ERROR] " + workflow_name + " → " + node_name;
const body = [
  "<h2>Error en workflow CTT</h2>",
  "<p><strong>Workflow:</strong> " + workflow_name + "</p>",
  "<p><strong>Nodo:</strong> " + node_name + "</p>",
  "<p><strong>Error:</strong> " + error_message + "</p>",
  shipping_code ? "<p><strong>Envio:</strong> " + shipping_code + "</p>" : "",
  "<p><strong>Ejecucion:</strong> <a href="" + execution_url + "">" + execution_id + "</a></p>",
  "<p><strong>Fecha:</strong> " + new Date().toISOString().replace("T"," ").substring(0,19) + "</p>"
].filter(Boolean).join("
");

return { subject, body };
